package simulation.events.eventQueue;

import simulation.events.Event;
import simulation.events.EventQueueEmptyException;

public class ArrayEventQueue implements EventQueue {
    private static final int DEFAULT_SIZE = 100;
    Event[] events;
    int eventCount;

    public ArrayEventQueue() {
        this(DEFAULT_SIZE);
    }

    public ArrayEventQueue(int size) {
        events = new Event[size];
    }

    @Override
    public void add(Event newEvent) { //check
        ensureEventsSize(1);
        int i = 0;
        while (i != eventCount && events[i].getTime() > newEvent.getTime()) i++;
        shiftEventsArray(i, 1);
        events[i++] = newEvent;
    }

    private void ensureEventsSize(int desiredAdditionalSize) {
        if (eventCount + desiredAdditionalSize >= events.length) {
            Event[] newEvents =
                    new Event[(eventCount + desiredAdditionalSize) * 2];
            System.arraycopy(events, 0, newEvents, 0, eventCount);
            events = newEvents;
        }
    }

    private void shiftEventsArray(int startPos, int shiftSize) {
        if (startPos == eventCount) return;
        System.arraycopy(events, startPos, events, startPos + shiftSize,
                eventCount - startPos);

    }

    @Override
    public Event fetch() throws EventQueueEmptyException {
        if (isEmpty()) throw new EventQueueEmptyException("q emty");
        Event event = events[--eventCount];
        events[eventCount] = null;
        return event;
    }

    public Event peak() throws EventQueueEmptyException {
        if (isEmpty()) throw new EventQueueEmptyException("q emty");
        return events[eventCount - 1];
    }
    @Override
    public boolean isEmpty() {
        return eventCount == 0;
    }
}

package simulation.events.eventQueue;

import simulation.events.Event;
import simulation.events.EventQueueEmptyException;

public class ArrayEventQueue implements EventQueue {
    private static final int DEFAULT_SIZE = 100;
    Event[] events;
    int eventCount;

    public ArrayEventQueue() {
        this(DEFAULT_SIZE);
    }

    public ArrayEventQueue(int size) {
        events = new Event[size];
        eventCount = 0;
    }

    @Override
    public void add(Event newEvent) {
        ensureEventsSize(1);
        int i = 0;
        while (i < eventCount && events[i].getTime() > newEvent.getTime()) {
            i++;
        }
        shiftEventsArray(i, 1);
        events[i] = newEvent;
        eventCount++;
    }

    private void ensureEventsSize(int desiredAdditionalSize) {
        if (eventCount + desiredAdditionalSize >= events.length) {
            Event[] newEvents =
                    new Event[(eventCount + desiredAdditionalSize) * 2];
            System.arraycopy(events, 0, newEvents, 0, eventCount);
            events = newEvents;
        }
    }

    private void shiftEventsArray(int startPos, int shiftSize) {
        if (startPos == eventCount) return;
        System.arraycopy(events, startPos, events, startPos + shiftSize,
                eventCount - startPos);

    }

    @Override
    public Event fetch() throws EventQueueEmptyException {
        if (isEmpty()) throw new EventQueueEmptyException("q emty");
        Event event = events[--eventCount];
        events[eventCount] = null;
        return event;
    }

    public Event peak() throws EventQueueEmptyException {
        if (isEmpty()) throw new EventQueueEmptyException("q emty");
        return events[eventCount - 1];
    }
    @Override
    public boolean isEmpty() {
        return eventCount == 0;
    }
}

package timeUtils;

public class TimeOperators {
    public static int expandAbsoluteTime(int hh, int mm, int ss) {
        return ss + 60 * mm + 3600 * hh;
    }

    public static int expandRelativeTime(int hh1, int mm1, int ss1, int hh2, int mm2, int ss2) {
        int time1 = expandAbsoluteTime(hh1, mm1, ss1);
        int time2 = expandAbsoluteTime(hh2, mm2, ss2);
        return time2 - time1;
    }
    public static String formatTime(int time) {
        int hh = time / 3600;
        int mm = (time % 3600) / 60;
        int ss = time % 60;
        return String.format("%02d:%02d:%02d", hh, mm, ss);
    }

}

package timeUtils;

public class TimeOperators {
    public static int expandAbsoluteTime(int hh, int mm, int ss) {
        return ss + 60 * mm + 3600 * hh;
    }

    public static int expandRelativeTime(int hh1, int mm1, int ss1, int hh2, int mm2, int ss2) {
        int time1 = expandAbsoluteTime(hh1, mm1, ss1);
        int time2 = expandAbsoluteTime(hh2, mm2, ss2);
        return time2 - time1;
    }
    public static String formatTime(int time) {
        int hh = time / 3600;
        int mm = (time % 3600) / 60;
        int ss = time % 60;
        return String.format("%02d:%02d:%02d", hh, mm, ss);
    }
    public static int expandTime(int hh, int mm, int ss) {
        return expandAbsoluteTime(hh, mm, ss);
    }

}
